test('dashboard returns empty counts for no invoices', () => {
  const result = dashboard([], '2026-11-07');
  assert.deepEqual(result.counts, { draft: 0, issued: 0, partially_paid: 0, paid: 0 });
});

test('dashboard counts invoices by status', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(inv2.ok, true);

  const issued1 = issueInvoice(inv1.value, []);
  assert.equal(issued1.ok, true);

  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  assert.equal(issued2.ok, true);

  const paid = recordPayment(issued1.value, { amount: invoiceTotals(issued1.value).total, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const invoices = [inv2.value, issued2.value, paid.value];

  const result = dashboard(invoices, '2026-11-07');
  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.partially_paid, 0);
  assert.equal(result.counts.paid, 1);
});

