test('dashboard identifies top customers by outstanding amount', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv1.ok, true);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 8 }],
  });
  assert.equal(inv2.ok, true);

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  assert.equal(inv3.ok, true);

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);
  const issued3 = issueInvoice(inv3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const invoices = [issued1.value, issued2.value, issued3.value];
  const result = dashboard(invoices, '2026-10-07');

  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C-002');
  assert(result.topCustomers[0].due > result.topCustomers[1].due);
  assert(result.topCustomers[1].due > result.topCustomers[2].due);
});

test('dashboard limits top customers to 3', () => {
  const invoices = [];
  for (let i = 1; i <= 5; i++) {
    const inv = createInvoice({
      customerId: `C-00${i}`,
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: i }],
    });
    assert.equal(inv.ok, true);

    const issued = issueInvoice(inv.value, invoices.map((_, idx) => `INV-2026-${String(idx + 1).padStart(4, '0')}`));
    assert.equal(issued.ok, true);
    invoices.push(issued.value);
  }

  const result = dashboard(invoices, '2026-10-07');
  assert.equal(result.topCustomers.length, 3);
});

