test('dashboard handles partially paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(inv.ok, true);

  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);

  const totals = invoiceTotals(issued.value);
  const partially = recordPayment(issued.value, { amount: Math.floor(totals.total / 2), date: '2026-10-09' });
  assert.equal(partially.ok, true);

  const result = dashboard([partially.value], '2026-10-07');
  assert.equal(result.counts.partially_paid, 1);
  assert(result.outstanding > 0);
});
